  1	/**
  2	 * Tests for src/gui/queue/validate-entry.ts — WP-005
  3	 *
  4	 * Verifies:
  5	 *   AC-1: At least 10 test cases for isRawQueueEntry().
  6	 *   AC-2: Tests import directly from validate-entry.js (no filesystem setup).
  7	 *   AC-3: All 5 validation rules exercised:
  8	 *         (a) non-null object check
  9	 *         (b) string id
 10	 *         (c) positive integer pid
 11	 *         (d) string planPath
 12	 *         (e) non-empty non-whitespace expectedSlug and string startedAt
 13	 *   AC-4: All tests pass when run via `npm test` in mcp-server/.
 14	 *   AC-5: Pure-function tests — no filesystem or I/O setup.
 15	 */
 16	
 17	import { describe, it, expect } from 'vitest';
 18	import { isRawQueueEntry } from '../../../src/gui/queue/validate-entry.js';
 19	
 20	// ---------------------------------------------------------------------------
 21	// Helpers
 22	// ---------------------------------------------------------------------------
 23	
 24	/** A canonical valid entry that satisfies every validation rule. */
 25	const VALID_ENTRY = {
 26	  id:           'run-abc-123',
 27	  pid:          42,
 28	  planPath:     '/fake/plans/2026-05-20-my-feature',
 29	  expectedSlug: '2026-05-20-my-feature',
 30	  startedAt:    '2026-05-20T00:00:00Z',
 31	  status:       'pending' as const,
 32	};
 33	
 34	// ---------------------------------------------------------------------------
 35	// Happy-path: valid entry
 36	// ---------------------------------------------------------------------------
 37	
 38	describe('isRawQueueEntry — valid entry', () => {
 39	  it('TC-01: returns true for a fully valid entry', () => {
 40	    expect(isRawQueueEntry(VALID_ENTRY)).toBe(true);
 41	  });
 42	});
 43	
 44	// ---------------------------------------------------------------------------
 45	// Rule (a): non-null object check
 46	// ---------------------------------------------------------------------------
 47	
 48	describe('isRawQueueEntry — (a) non-null object check', () => {
 49	  it('TC-02: returns false for null', () => {
 50	    expect(isRawQueueEntry(null)).toBe(false);
 51	  });
 52	
 53	  it('TC-03: returns false for a primitive string', () => {
 54	    expect(isRawQueueEntry('not-an-object')).toBe(false);
 55	  });
 56	
 57	  it('TC-04: returns false for a number', () => {
 58	    expect(isRawQueueEntry(42)).toBe(false);
 59	  });
 60	
 61	  it('TC-05: returns false for undefined', () => {
 62	    expect(isRawQueueEntry(undefined)).toBe(false);
 63	  });
 64	});
 65	
 66	// ---------------------------------------------------------------------------
 67	// Rule (b): string id
 68	// ---------------------------------------------------------------------------
 69	
 70	describe('isRawQueueEntry — (b) string id', () => {
 71	  it('TC-06: returns false when id is missing', () => {
 72	    const { id: _removed, ...entry } = VALID_ENTRY;
 73	    expect(isRawQueueEntry(entry)).toBe(false);
 74	  });
 75	
 76	  it('TC-07: returns false when id is a number', () => {
 77	    expect(isRawQueueEntry({ ...VALID_ENTRY, id: 99 })).toBe(false);
 78	  });
 79	});
 80	
 81	// ---------------------------------------------------------------------------
 82	// Rule (c): positive integer pid
 83	// ---------------------------------------------------------------------------
 84	
 85	describe('isRawQueueEntry — (c) positive integer pid', () => {
 86	  it('TC-08: returns false when pid is zero', () => {
 87	    expect(isRawQueueEntry({ ...VALID_ENTRY, pid: 0 })).toBe(false);
 88	  });
 89	
 90	  it('TC-09: returns false when pid is negative', () => {
 91	    expect(isRawQueueEntry({ ...VALID_ENTRY, pid: -1 })).toBe(false);
 92	  });
 93	
 94	  it('TC-10: returns false when pid is a float', () => {
 95	    expect(isRawQueueEntry({ ...VALID_ENTRY, pid: 1.5 })).toBe(false);
 96	  });
 97	});
 98	
 99	// ---------------------------------------------------------------------------
100	// Rule (d): string planPath

101	// ---------------------------------------------------------------------------
102	
103	describe('isRawQueueEntry — (d) string planPath', () => {
104	  it('TC-11: returns false when planPath is missing', () => {
105	    const { planPath: _removed, ...entry } = VALID_ENTRY;
106	    expect(isRawQueueEntry(entry)).toBe(false);
107	  });
108	
109	  it('TC-12: returns false when planPath is null', () => {
110	    expect(isRawQueueEntry({ ...VALID_ENTRY, planPath: null })).toBe(false);
111	  });
112	});
113	
114	// ---------------------------------------------------------------------------
115	// Rule (e): non-empty non-whitespace expectedSlug and string startedAt
116	// ---------------------------------------------------------------------------
117	
118	describe('isRawQueueEntry — (e) expectedSlug and startedAt', () => {
119	  it('TC-13: returns false when expectedSlug is an empty string', () => {
120	    expect(isRawQueueEntry({ ...VALID_ENTRY, expectedSlug: '' })).toBe(false);
121	  });
122	
123	  it('TC-14: returns false when expectedSlug is whitespace-only', () => {
124	    expect(isRawQueueEntry({ ...VALID_ENTRY, expectedSlug: '   ' })).toBe(false);
125	  });
126	
127	  it('TC-15: returns false when expectedSlug is missing', () => {
128	    const { expectedSlug: _removed, ...entry } = VALID_ENTRY;
129	    expect(isRawQueueEntry(entry)).toBe(false);
130	  });
131	
132	  it('TC-16: returns false when startedAt is missing', () => {
133	    const { startedAt: _removed, ...entry } = VALID_ENTRY;
134	    expect(isRawQueueEntry(entry)).toBe(false);
135	  });
136	
137	  it('TC-17: returns false when startedAt is a number', () => {
138	    expect(isRawQueueEntry({ ...VALID_ENTRY, startedAt: 1234567890 })).toBe(false);
139	  });
140	});

